"Отправить":"Senden",
"Общий разговор Ловчих.":"Allgemeiner Plausch der Fänger.",
"Торговля: договаривайтесь о сделках — сами сделки идут через Аукцион.":"Handel: Macht Deals aus — abgewickelt wird über die Auktion.",
"Ищите команду для Разломов: пишите код комнаты и место.":"Sucht ein Team für Risse: Schreibt Raumcode und Ort.",
"Вопросы новичков и советы бывалых.":"Fragen von Neulingen, Tipps von Profis.",
"Канал твоей дружины — его видят только свои.":"Kanal deines Clans — nur für Mitglieder.",
"Сегодня":"Heute",
"Вчера":"Gestern",
"Ссылки запрещены, грубость скрывается.":"Links sind verboten, Beleidigungen werden ausgeblendet.",
"Правила чата":"Chatregeln",
"Скрытых Ловчих: {0} · Вернуть":"Ausgeblendete Fänger: {0} · Einblenden",
"ур. {0}":"Lv. {0}",
"Здесь пока тихо":"Hier ist es noch still",
"Напиши первым — тебя увидят все Ловчие твоей дружины.":"Schreib als Erster — alle Fänger deines Clans sehen es.",
"Напиши первым — тебя увидят все Ловчие Ордена.":"Schreib als Erster — alle Fänger des Ordens sehen es.",
"Новые сообщения: {0}":"Neue Nachrichten: {0}",
"Пожаловаться?":"Melden?",
"На сообщение Ловчего «{0}». После трёх жалоб от разных Ловчих оно скрывается для всех.":"Nachricht von Fänger „{0}“. Nach drei Meldungen verschiedener Fänger wird sie für alle ausgeblendet.",
"Пожаловаться":"Melden",
"Жалоба отправлена — спасибо":"Meldung gesendet — danke",
"Скрыть сообщения?":"Nachrichten ausblenden?",
"Сообщения Ловчего «{0}» перестанут показываться на этом телефоне. Вернуть можно в любой момент — строкой «Скрытых Ловчих» вверху чата.":"Nachrichten von Fänger „{0}“ werden auf diesem Handy nicht mehr angezeigt. Einblenden kannst du sie jederzeit über „Ausgeblendete Fänger“ oben im Chat.",
"Скрыть":"Ausblenden",
"Скрыто. Вернуть — «Скрытых Ловчих» вверху чата":"Ausgeblendet. Einblenden über „Ausgeblendete Fänger“ oben im Chat",
"Дружину можно выбрать с {0} уровня":"Einen Clan kannst du ab Level {0} wählen",
"Выбери дружину":"Wähle einen Clan",
"Дружины Ордена держат Капища: поставь своего духа защитником — и Капище окрасится цветом твоей дружины, а тебе каждый день будет приходить дань. Выбор — навсегда.":"Die Clans des Ordens halten die Kapishche: Stell einen Geist als Verteidiger auf — dann färbt sich das Kapishche in der Farbe deines Clans, und du bekommst täglich Tribut. Die Wahl gilt für immer.",
"Позже":"Später",
"Вступить в «{0}»? Сменить дружину потом нельзя.":"„{0}“ beitreten? Den Clan kannst du danach nicht wechseln.",
"Вступить":"Beitreten",
"Ты в «{0}»! Побеждай на Капищах и ставь защитников.":"Du bist bei „{0}“! Siege an Kapishche und stell Verteidiger auf.",
"Кого поставить защитником?":"Wer soll verteidigen?",
"Дух останется у тебя: на Капище встанет его отражение. Пока он стоит, раз в день приходит дань — ✦ {0} и оберег.":"Der Geist bleibt bei dir: Am Kapishche steht sein Abbild. Solange es steht, bekommst du täglich Tribut — ✦ {0} und einen Talisman.",
"Отражение стоит до {0} суток: первые {1} ч в полной силе, потом устаёт и слабеет, а затем возвращается домой. Защитники — не больше чем на {2} Капищах.":"Das Abbild steht bis zu {0} Tage: die ersten {1} Std. mit voller Kraft, dann wird es müde und schwächer und kehrt schließlich heim. Verteidiger — höchstens an {2} Kapishche.",
"Защитник встал на Капище «{0}» — оно под знаменем «{1}»":"Verteidiger steht am Kapishche „{0}“ — es gehört jetzt zu „{1}“",
"Срок на посту вышел — защитники вернулись с {0}. За службу: {1}":"Die Dienstzeit ist um — die Verteidiger sind zurück mit {0}. Für den Dienst: {1}",
"Защитники вернулись с {0}: соперники победили. За службу: {1}":"Verteidiger zurück von {0}: Die Gegner haben gesiegt. Lohn für den Dienst: {1}",
"Защитник вернулся с {0}: соперники победили. За службу: {1}":"Verteidiger zurück von {0}: Die Gegner haben gesiegt. Lohn für den Dienst: {1}",
"Дружина":"Clan",
"Узнаём, как дела у дружин…":"Wir fragen die Clans, wie es läuft…",
"меньше часа":"unter 1 Std.",
"{0} ч":"{0} Std.",
"на посту {0} · защитников {1} из {2}":"im Dienst {0} · Verteidiger {1} von {2}",
"устал: уровень −{0}% · домой через {1} ч":"müde: Level −{0}% · heim in {1} Std.",
"в полной силе ещё {0} ч":"volle Kraft noch {0} Std.",
"Капища рядом (≈5 км)":"Kapishche in der Nähe (≈5 km)",
"Капища по всей России":"Kapishche in ganz Russland",
"Мои защитники":"Meine Verteidiger",
"{0} из {1}":"{0} von {1}",
"Пока нигде. Победи на Капище и поставь защитника — каждый день будет приходить дань.":"Noch nirgends. Siege an einem Kapishche und stell einen Verteidiger auf — dann kommt täglich Tribut.",
"Дань — ✦ {0}, оберег и {1} {2} в день за каждое Капище, где твой защитник отстоял хотя бы {3} ч. Защитник стоит до {4} суток и понемногу устаёт; если соперники его победят или срок выйдет, он вернётся с искрами за время на посту. Часть Капищ — вольные: их не держит ни одна дружина.":"Tribut — ✦ {0}, ein Talisman und {1} {2} pro Tag für jedes Kapishche, an dem dein Verteidiger mindestens {3} Std. stand. Ein Verteidiger steht bis zu {4} Tage und wird allmählich müde; besiegen ihn Gegner oder läuft die Zeit ab, kehrt er mit Funken für die Zeit auf dem Posten zurück. Manche Kapishche sind frei: Kein Clan hält sie.",
