"Славянская":"Slawisch",
"Россия, Восточная Европа, Кавказ и Средняя Азия":"Russland, Osteuropa, Kaukasus und Zentralasien",
"Греческая":"Griechisch",
"Средиземноморье: Греция, Италия, Испания, Турция":"Mittelmeerraum: Griechenland, Italien, Spanien, Türkei",
"Скандинавская":"Nordisch",
"Скандинавия, Исландия, Дания, Германия, Прибалтика":"Skandinavien, Island, Dänemark, Deutschland, Baltikum",
"Кельтская":"Keltisch",
"Ирландия, Британия, Франция, Бельгия, Нидерланды":"Irland, Großbritannien, Frankreich, Belgien, Niederlande",
"Египетская":"Ägyptisch",
"Египет, Северная Африка, Аравия и Ближний Восток":"Ägypten, Nordafrika, Arabien und der Nahe Osten",
"Китайская":"Chinesisch",
"Китай, Корея, Япония и Юго-Восточная Азия":"China, Korea, Japan und Südostasien",
"Ацтекская":"Aztekisch",
"Америка — от Аляски до Огненной Земли":"Amerika — von Alaska bis Feuerland",
"Оберег":"Talisman",
"Узелок с заговорённой травой. Бросай в духа, чтобы поймать.":"Ein Bündel mit verzaubertem Kraut. Wirf es auf einen Geist, um ihn zu fangen.",
"Серебряный оберег":"Silbertalisman",
"Серебро держит духов крепче. Шанс поимки ×1,5.":"Silber hält Geister fester. Fangchance ×1,5.",
"Золотой оберег":"Goldtalisman",
"Лучший оберег Ордена. Шанс поимки ×2.":"Der beste Talisman des Ordens. Fangchance ×2.",
"Духи обожают мёд. Успокаивает духа: шанс поимки ×1,5 на один бросок.":"Geister lieben Honig. Beruhigt den Geist: Fangchance ×1,5 für einen Wurf.",
"Подорожник":"Wegerich",
"Лист к ране — и полегчало. Возвращает духу четверть здоровья.":"Ein Blatt auf die Wunde — schon besser. Gibt einem Geist ein Viertel Gesundheit zurück.",
"Целебный отвар":"Heiltrank",
"Травы Велеса, сваренные в родниковой воде. Возвращает духу 60% здоровья.":"Kräuter des Veles, in Quellwasser gekocht. Gibt einem Geist 60% Gesundheit zurück.",
"Мёртвая вода":"Myortvaya Voda",
"Редкая сказочная вода, что сращивает самые тяжкие раны. Дух без сил поднимется на 4 часа раньше. Живых не лечит.":"Seltenes Märchenwasser, das selbst die schwersten Wunden schließt. Ein erschöpfter Geist steht 4 Stunden früher auf. Heilt keine Geister, die noch stehen.",
"Живая вода":"Zhivaya Voda",
"Возвращает духу половину здоровья, а в разломе — лечит прямо в бою. Духа без сил не поднимет.":"Gibt einem Geist die Hälfte seiner Gesundheit zurück und heilt im Riss mitten im Kampf. Erschöpfte Geister weckt es nicht.",
"Ладан":"Weihrauch",
"Дымок приманивает духов: 30 минут их вокруг вдвое больше.":"Der Rauch lockt Geister an: 30 Minuten lang doppelt so viele um dich herum.",
"Дальний пропуск":"Fernpass",
"Грамота Ордена: закрыть Разлом до 5 км от тебя, не подходя к нему. Один Орден дарит каждый день.":"Urkunde des Ordens: Schließe einen Riss bis 5 km entfernt, ohne hinzugehen. Einen schenkt dir der Orden jeden Tag.",
"Настой опыта":"EP-Trank",
"Медовый настой на травах Велеса: сутки опыта на четверть больше.":"Ein Honigtrank mit Kräutern des Veles: einen Tag lang ein Viertel mehr EP.",
"Подарок":"Geschenk",
"Узелок для друга: обереги, мёд, иногда кокон. Отправляется в «Меню → Друзья», раз в день каждому.":"Ein Bündel für Freunde: Talismane, Honig, manchmal ein Kokon. Verschicken unter „Menü → Freunde“, jedem einmal am Tag.",
"Знакомый":"Bekannter",
"Приятель":"Kumpel",
