"Преврати одного духа":"Entwickle einen Geist",
"Закрой разлом":"Schließe einen Riss",
"Сфотографируй духа во время встречи":"Fotografiere einen Geist bei einer Begegnung",
"Преврати духа":"Entwickle einen Geist",
"Победи хранителя капища":"Besiege den Hüter eines Kapishche",
"Выведи духа из кокона":"Lass einen Geist aus einem Kokon schlüpfen",
"Освободи родник от прислужников Нави":"Befreie eine Quelle von Dienern der Nav",
"2031 год. Геомагнитная буря, которую потом назовут <b>Тонкой ночью</b>, истончила границу между Явью — нашим миром — и Навью, миром духов.":"Im Jahr 2031 schwächte ein geomagnetischer Sturm, später <b>Dünne Nacht</b> genannt, die Grenze zwischen Yav — unserer Welt — und Nav, der Welt der Geister.",
"Теперь по улицам бродят духи. Древние — Леший, Водяной, Домовой. И новые, рождённые городом: Вайфайка, Трамвайник, Фонарник.":"Jetzt streifen Geister durch die Straßen. Uralte wie Leshy, Vodyanoy und Domovoy. Und neue, von der Stadt geboren: Vayfayka, Tramvaynik, Fonarnik.",
"Древний <b>Орден Оберега</b> снова набирает Ловчих. Твоя задача — находить духов, ловить их оберегами, черпать силу из родников и закрывать разломы, откуда лезет всё самое опасное.":"Der uralte <b>Orden des Talismans</b> sucht wieder Fänger. Deine Aufgabe: Geister finden, sie mit Talismanen fangen, Kraft aus Quellen schöpfen und Risse schließen, aus denen das Gefährlichste kriecht.",
"Ясно":"Klar",
"Переменная облачность":"Teils bewölkt",
"Пасмурно":"Bedeckt",
"Туман":"Nebel",
"Дождь":"Regen",
"Снег":"Schnee",
"Гроза":"Gewitter",
"Ветрено":"Windig",
"Полнолуние":"Vollmond",
"Ночью духи Тени и Воды встречаются чаще, а Русалки и Навки выходят к людям.":"Nachts trifft man öfter Geister von Schatten und Wasser, und Rusalkas und Navkas kommen zu den Menschen.",
"Новолуние":"Neumond",
"В безлунную ночь сияющие духи встречаются вдвое чаще.":"In mondlosen Nächten sind schillernde Geister doppelt so häufig.",
"Бронза":"Bronze",
"Серебро":"Silber",
"Золото":"Gold",
