"Закрой разломов":"Schließe Risse",
"Летописец":"Chronist",
"Видов духов в бестиарии":"Geisterarten im Bestiarium",
"Странник миров":"Weltenwanderer",
"Видов духов других мифологий":"Geisterarten anderer Mythologien",
"Очиститель":"Reiniger",
