"Цветёт папоротник: Купалинка повсюду, духи Огня, Воды и Леса чаще, ночью сияющие — вдвое чаще.":"Der Farn blüht: Kupalinka ist überall, Feuer-, Wasser- und Waldgeister sind häufiger, nachts gibt es doppelt so viele schillernde.",
"Покров":"Pokrov",
"Первые туманы и иней: духи Ветра и Воды встречаются чаще, Листопадница — повсюду, в родниках больше добычи.":"Erste Nebel und Raureif: Wind- und Wassergeister sind häufiger, Listopadnitsa ist überall, Quellen geben mehr Beute.",
"Велесова ночь":"Veles-Nacht",
"Граница миров тоньше всего: духи Тени втрое чаще, в великих разломах ждёт Кощей, сияющие Тени вдвое чаще.":"Die Grenze der Welten ist am dünnsten: Schattengeister dreimal so häufig, in Großen Rissen wartet Koschei, schillernde Schatten doppelt so oft.",
