"Победи хранителей капищ: {0}":"Besiege Hüter von Kapishche: {0}",
"Первый дух":"Der erste Geist",
"Твои духи":"Deine Geister",
"Родники":"Quellen",
"Прогулки":"Spaziergänge",
"Рядом появился дух — видишь светящийся круг на карте? <b>Коснись духа</b>, а потом <b>смахни оберег вверх</b>, прямо в него.":"Ein Geist ist in der Nähe — siehst du den leuchtenden Kreis auf der Karte? <b>Tippe den Geist an</b> und <b>wische den Talisman nach oben</b>, direkt auf ihn.",
"Второй учебный дух рядом. Кольцо вокруг духа сжимается: бросай, когда оно <b>маленькое</b>, — выйдет «Отлично!». Зелёное кольцо — дух покладистый, красное — упрямый.":"Der zweite Übungsgeist ist in der Nähe. Der Ring um den Geist schrumpft: Wirf, wenn er <b>klein</b> ist — dann gibt es „Super!“. Grüner Ring — umgänglicher Geist, roter — sturer Geist.",
"Это меню — здесь все разделы. Пока открыто не всё: разделы откроются по ходу обучения, подсвеченный — следующий.":"Das ist das Menü — hier sind alle Bereiche. Noch ist nicht alles offen: Bereiche öffnen sich im Laufe des Tutorials, der hervorgehobene ist der nächste.",
"Каждый пойманный дух — твой. Открой <b>меню</b> — золотой оберег внизу экрана.":"Jeder gefangene Geist gehört dir. Öffne das <b>Menü</b> — der goldene Talisman unten am Bildschirm.",
"Это твоя коллекция — все пойманные духи. Сверху — сортировка по силе, новизне и имени и фильтр по стихиям.":"Das ist deine Sammlung — alle gefangenen Geister. Oben kannst du nach Kraft, Neuheit und Name sortieren und nach Elementen filtern.",
"Это разделы Ордена. Открой <b>«Духи»</b> — там твоя коллекция.":"Das sind die Bereiche des Ordens. Öffne <b>„Geister“</b> — dort ist deine Sammlung.",
"Это карточка духа: сила, стихия, приёмы и семейство. Ниже — кнопки «Усилить» и «Превратить», а ещё можно сделать духа спутником.":"Das ist die Karte des Geistes: Kraft, Element, Attacken und Familie. Darunter die Buttons „Stärken“ und „Entwickeln“, und du kannst ihn zum Begleiter machen.",
"Коснись любого духа, чтобы открыть его <b>карточку</b>.":"Tippe einen Geist an, um seine <b>Karte</b> zu öffnen.",
"На карточке — сила духа. Нажми <b>«Усилить»</b>: за искры и эссенцию дух станет сильнее. Эссенцию приносят поимки духов того же семейства.":"Auf der Karte steht die Kraft des Geistes. Tippe auf <b>„Stärken“</b>: Für Funken und Essenz wird er stärker. Essenz bekommst du durch Fänge derselben Familie.",
"Бестиарий — все виды духов. Пойманные видны целиком, встреченные — тенью. Коснись вида, чтобы прочитать о нём.":"Das Bestiarium zeigt alle Geisterarten. Gefangene siehst du ganz, gesichtete als Schatten. Tippe eine Art an, um mehr zu lesen.",
"Теперь загляни в <b>«Бестиарий»</b> (меню) — там все виды духов. Сколько найдёшь ты?":"Schau jetzt ins <b>„Bestiarium“</b> (Menü) — dort sind alle Geisterarten. Wie viele findest du?",
"Обереги пополняют <b>родники</b> — синие колодцы у памятников, фонтанов и храмов. Иди к ближайшему по <b>стрелке вверху</b> и коснись его. Если рядом нет — прогуляйся.":"Talismane füllst du an <b>Quellen</b> auf — blauen Brunnen bei Denkmälern, Springbrunnen und Kirchen. Folge dem <b>Pfeil oben</b> zur nächsten und tippe sie an. Ist keine in der Nähe, geh ein Stück.",
"Сумка: обереги, мёд, живая вода и ладан. Сверху видно, сколько ещё поместится; лишнее можно выбросить.":"Die Tasche: Talismane, Honig, Zhivaya Voda und Weihrauch. Oben siehst du, wie viel noch reinpasst; Überflüssiges kannst du wegwerfen.",
"Добыча уже в <b>Сумке</b>. Открой меню → «Сумка» и посмотри, что у тебя есть.":"Die Beute ist schon in der <b>Tasche</b>. Öffne Menü → „Tasche“ und sieh nach, was du hast.",
"Коконы греются шагами — одновременно можно греть три. Готовый кокон вылупится одним касанием. А твой первый дух идёт рядом — это спутник: в пути он находит эссенцию.":"Kokons werden durch Schritte gewärmt — drei gleichzeitig. Ein fertiger Kokon schlüpft mit einem Tippen. Und dein erster Geist läuft neben dir — dein Begleiter: Unterwegs findet er Essenz.",
"Открой меню → <b>«Коконы»</b>. Первый кокон уже греется — пройди 2 км, и он вылупится.":"Öffne Menü → <b>„Kokons“</b>. Der erste Kokon wird schon gewärmt — lauf 2 km, dann schlüpft er.",
"Здесь задания дня — они обновляются в полночь. А родники иногда дают поручения: выполнишь — встретишь особого духа.":"Hier sind die Tagesquests — sie erneuern sich um Mitternacht. Und Quellen geben manchmal Aufträge: Erfüllst du einen, triffst du einen besonderen Geist.",
"Открой <b>«Задания»</b> — там задания дня.":"Öffne <b>„Quests“</b> — dort sind die Tagesquests.",
"Путь Ловчего: что откроется на каждом уровне и какие награды ждут. Звания растут: Послушник, Ловчий, Следопыт, Ведун, Хранитель.":"Pfad des Fängers: was jedes Level freischaltet und welche Belohnungen warten. Die Titel steigen: Novize, Fänger, Spurenleser, Seher, Hüter.",
"И последнее: открой <b>«Путь»</b> в меню — там видно, что откроется на каждом уровне Ловчего.":"Und zuletzt: Öffne <b>„Pfad“</b> im Menü — dort siehst du, was jedes Fänger-Level freischaltet.",
