"Защитники «{0}» отступили — Капище «{1}» свободно!":"Die Verteidiger von „{0}“ sind abgezogen — das Kapishche „{1}“ ist frei!",
"Победа засчитана, но пока шёл бой, на Капище сменились защитники.":"Sieg gewertet, aber während des Kampfes haben am Kapishche die Verteidiger gewechselt.",
"«Достойно, Ловчий», — {0} склоняет голову. Капище «{1}» освящено тобой до конца дня.":"„Würdig, Fänger“, sagt {0} und neigt den Kopf. Das Kapishche „{1}“ ist bis Tagesende von dir geweiht.",
"Победа!":"Sieg!",
"Поставь своего защитника — и Капище перейдёт твоей дружине.":"Stell deinen Verteidiger auf — dann gehört das Kapishche deinem Clan.",
"Поражение":"Niederlage",
"«Приходи, когда окрепнешь», — говорит {0}. Попробуй другую команду: смотри на стихии хранителя и береги щиты для его приёмов.":"„Komm wieder, wenn du stärker bist“, sagt {0}. Versuch ein anderes Team: Achte auf die Elemente des Hüters und spar deine Schilde für seine Attacken.",
"Хорошая тренировка! Награда за поединок с {0} сегодня уже получена.":"Gutes Training! Die heutige Belohnung für das Duell mit {0} hast du schon.",
"{0} жмёт тебе руку: «Честный бой!» Дружба крепнет.":"{0} schüttelt dir die Hand: „Fairer Kampf!“ Die Freundschaft wächst.",
"<b>+1 ★</b> дружбы":"<b>+1 ★</b> Freundschaft",
"Духи {0} оказались сильнее. Подбери команду против их стихий и попробуй снова — поединки с другом не ограничены.":"Die Geister von {0} waren stärker. Stell ein Team gegen ihre Elemente zusammen und versuch es nochmal — Duelle mit Freunden sind unbegrenzt.",
"Родник освобождён!":"Quelle befreit!",
"Прислужник растворился в тумане. Один из его духов — омрачённый {0} — остался рядом. Его ещё можно спасти!":"Der Diener hat sich im Nebel aufgelöst. Einer seiner Geister — ein verdunkelter {0} — ist noch da. Du kannst ihn retten!",
