"Соперник — живой Ловчий. Тапай — быстрая атака, она копит энергию; полная шкала — «Приём». Щиты берегут от его приёмов.":"Der Gegner ist ein echter Fänger. Tippen ist ein schneller Angriff und lädt Energie; Leiste voll — „Spezial“. Schilde schützen vor seinen Attacken.",
