"Этого духа не выпустить":"Dieser Geist kann nicht antreten",
"Бросай оберег, когда кольцо сжимается: «Отлично!» даёт больше опыта и шанс поимки.":"Wirf den Talisman, wenn der Ring schrumpft: „Super!“ bringt mehr EP und Fangchance.",
"Родники наполняются снова через несколько минут — прогулка по кругу приносит припасы.":"Quellen füllen sich nach ein paar Minuten wieder — eine Runde spazieren bringt Vorräte.",
"Спутник ходит с тобой и находит эссенцию своего семейства.":"Dein Begleiter läuft mit dir und findet Essenz seiner Familie.",
"В Лиге дерутся живые Ловчие: победа над сильным соперником даёт больше рейтинга, чем над слабым.":"In der Liga kämpfen echte Fänger: Ein Sieg über einen starken Gegner bringt mehr Wertung als über einen schwachen.",
"Разломы открываются у Капищ каждый час: собери команду из трёх духов.":"Risse öffnen sich stündlich an Kapishche: Stell ein Team aus drei Geistern zusammen.",
"Сияющие духи редки — их выдают искры вокруг.":"Schillernde Geister sind selten — man erkennt sie an Funken ringsum.",
"Коконы греются шагами: одновременно можно греть три.":"Kokons werden durch Schritte gewärmt: drei gleichzeitig.",
"Задания дня обновляются в полночь, а за все три ждёт Сундук дня.":"Tagesquests erneuern sich um Mitternacht, und für alle drei wartet die Tagestruhe.",
"Поставь защитника на Капище своей дружины — он принесёт искры.":"Stell einen Verteidiger an ein Kapishche deines Clans — er bringt Funken.",
"Погода усиливает духов своей стихии: в дождь чаще встречаются водные.":"Das Wetter stärkt Geister seines Elements: Bei Regen gibt es mehr Wassergeister.",
