"Вход через {0} перейдёт к твоему текущему Ловчему, а у {1} его больше не будет.":"Die Anmeldung über {0} geht an deinen aktuellen Fänger, {1} hat sie dann nicht mehr.",
"У того Ловчего есть и другие способы входа — его прогресс останется доступен через них.":"Dieser Fänger hat weitere Anmeldewege — sein Fortschritt bleibt darüber erreichbar.",
"<b>У того Ловчего не останется других способов входа — его прогресс станет недоступен навсегда.</b>":"<b>Dieser Fänger hat keinen anderen Anmeldeweg — sein Fortschritt ist dann für immer verloren.</b>",
