"Не удалось привязать — попробуй ещё раз":"Verknüpfen fehlgeschlagen — versuch es noch mal",
"Вход уже привязан":"Login schon verknüpft",
"Вход через {0} привязан к Ловчему {1}.":"Der Login über {0} gehört zu {1}.",
"Можно перейти в ту учётную запись — тогда текущий гостевой прогресс на этом устройстве останется в прежней учётной записи, вернуться в неё будет нельзя. Или привязать этот вход к текущему Ловчему.":"Du kannst zu diesem Konto wechseln — dein Gastfortschritt auf diesem Gerät bleibt im alten Konto, zurück geht es nicht. Oder diese Anmeldung mit deinem aktuellen Fänger verknüpfen.",
"Можно перейти в ту учётную запись — текущий прогресс останется в своей. Или привязать этот вход к текущему Ловчему.":"Du kannst zu diesem Konto wechseln — dein aktueller Fortschritt bleibt in seinem Konto. Oder diese Anmeldung mit deinem aktuellen Fänger verknüpfen.",
