"Гость играет только на этом устройстве — привяжи вход, чтобы не потерять прогресс":"Als Gast spielst du nur auf diesem Gerät — verknüpfe einen Login, damit nichts verloren geht",
"Привяжи вход — и прогресс откроется на любом устройстве":"Verknüpfe einen Login — dann hast du deinen Fortschritt auf jedem Gerät",
"Текущий прогресс останется в своей учётной записи":"Der aktuelle Fortschritt bleibt in seinem Konto",
"вход":"Login",
"Открываю {0}…":"Öffne {0}…",
"Выйти?":"Abmelden?",
"Прогресс останется в учётной записи — вернуться в неё можно тем же входом. На этом устройстве начнётся новая гостевая игра.":"Der Fortschritt bleibt im Konto — du kommst mit demselben Login zurück. Auf diesem Gerät startet ein neues Gastspiel.",
