"Выйти из гостевой игры?":"Gastspiel verlassen?",
"<b>Прогресс гостя пропадёт навсегда</b> — у гостя нет входа, чтобы вернуться.":"<b>Der Gastfortschritt geht für immer verloren</b> — ein Gast hat keinen Login für die Rückkehr.",
