"Не удалось загрузить карту. Проверь подключение к интернету.":"Karte konnte nicht geladen werden. Prüfe deine Internetverbindung.",
"Повторить":"Nochmal",
"{0} готов вылупиться!":"{0} ist bereit zum Schlüpfen!",
"Коконов готово: {0}. Загляни в меню!":"Fertige Kokons: {0}. Schau ins Menü!",
"Прогресс хранится на сервере игры, поэтому нужен интернет.":"Der Fortschritt liegt auf dem Spielserver, darum brauchst du Internet.",
"Проверяю обновления…":"Suche nach Updates…",
