"С {0} уровня духов можно пробуждать: каждая звезда поднимает предел уровня духа ещё на {1}, до {2}.":"Ab Level {0} kannst du Geister erwecken: Jeder Stern hebt ihr Levellimit um weitere {1}, bis {2}.",
