"Поблизости пока нет ни одного Родника, поэтому Орден раз в день присылает припасы: {0}.":"In der Nähe gibt es noch keine Quelle, deshalb schickt dir der Orden einmal am Tag Vorräte: {0}.",
"Знаешь интересное место рядом? Предложи его в «Меню → Места» — после проверки там появится Родник.":"Kennst du einen interessanten Ort in der Nähe? Schlag ihn unter „Menü → Orte“ vor — nach der Prüfung erscheint dort eine Quelle.",
