"Духи живут рядом с тобой":"Geister leben ganz in deiner Nähe",
"Игре нужна геопозиция, чтобы показать духов, родники и разломы вокруг. Прогресс хранится на сервере игры и доступен только тебе; сервер проверяет каждое действие (поэтому нужен интернет), в прогрессе есть дневник с местами поимок. Для проверки действий на карте сервер получает твоё местоположение. Чтобы загрузить места на карте и погоду, район (~1 км) запрашивается у OpenStreetMap и Open-Meteo (погоду можно выключить в настройках). Точные координаты уходят на сервер, только если ты сам предложишь новое место.":"Das Spiel braucht deinen Standort, um Geister, Quellen und Risse in der Nähe zu zeigen. Dein Fortschritt liegt auf dem Spielserver und ist nur für dich zugänglich; der Server prüft jede Aktion (darum brauchst du Internet), und zum Fortschritt gehört ein Tagebuch mit Fangorten. Um Aktionen auf der Karte zu prüfen, erhält der Server deinen Standort. Um Orte auf der Karte und das Wetter zu laden, wird dein Gebiet (~1 km) bei OpenStreetMap und Open-Meteo abgefragt (Wetter lässt sich in den Einstellungen abschalten). Genaue Koordinaten gehen nur an den Server, wenn du selbst einen neuen Ort vorschlägst.",
"Разрешить геопозицию":"Standort erlauben",
"Уже играешь?":"Spielst du schon?",
"Войди — и твой прогресс откроется на этом устройстве":"Log dich ein — dann hast du deinen Fortschritt auf diesem Gerät",
"Назови себя":"Gib dir einen Namen",
"Новое приложение":"Neue App",
"Игра переехала на свой сервер в России — <b>duholov.ru</b>. Для этого вышло новое приложение: его нужно установить заново.":"Das Spiel ist auf einen eigenen Server in Russland umgezogen — <b>duholov.ru</b>. Dafür gibt es eine neue App, die du neu installieren musst.",
"Привяжи вход: Меню → Настройки → Учётная запись (Google, Яндекс, VK, Telegram или почта). Без этого прогресс гостя не перенесётся.":"Verknüpfe einen Login: Menü → Einstellungen → Konto (Google, Yandex, VK, Telegram oder E-Mail). Sonst wird der Gastfortschritt nicht übernommen.",
"Удали это приложение.":"Lösche diese App.",
