"Вышла новая версия приложения Духолов для Android. Скачайте её и установите поверх текущей — прогресс сохранится.":"Eine neue Version der Dukholov-App für Android ist da. Lade sie herunter und installiere sie über die aktuelle — dein Fortschritt bleibt erhalten.",
